package com.lbos.commercecustomer.service; import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.client.OrderLogisticsClient;import com.lbos.commercecustomer.client.PartnerVerificationClient;import com.lbos.commercecustomer.dto.client.order.LineServiceabilityResult;import com.lbos.commercecustomer.dto.client.order.ServiceabilityResponse;import com.lbos.commercecustomer.dto.request.CartItemRequest;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.exception.InsufficientStockException;import com.lbos.commercecustomer.repository.*;import com.lbos.commercecustomer.service.impl.*;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.Test; class CartServiceImplTest {private static RetailerEnrichmentSupport noRetailerEnrichment(){return new RetailerEnrichmentSupport(mock(PartnerVerificationClient.class),new FeignCallSupport());}@Test void boundaryQuantityEqualsStockAllowed(){var carts=mock(CustomerCartRepository.class);var items=mock(CustomerCartItemRepository.class);var products=mock(ProductRepository.class);var ctx=mock(ContextSupport.class);var wish=mock(WishlistServiceImpl.class);var c=new CustomerProfile();c.setId(UUID.randomUUID());var p=new Product();p.setId(1L);p.setName("P");p.setStatus(com.lbos.commercecustomer.enums.ProductStatus.ACTIVE);p.setStock(5);p.setUnitPrice(BigDecimal.ONE);p.setRetailerId(UUID.randomUUID());when(ctx.customer()).thenReturn(c);when(products.findById(1L)).thenReturn(Optional.of(p));when(carts.findByCustomerIdAndProductId(c.getId(),1L)).thenReturn(Optional.empty());when(carts.save(any())).thenAnswer(x->{CustomerCart a=x.getArgument(0);a.setId(UUID.randomUUID());return a;});when(items.findByCartId(any())).thenReturn(Optional.empty());when(items.save(any())).thenAnswer(x->{CustomerCartItem i=x.getArgument(0);i.setId(UUID.randomUUID());return i;});var addresses=mock(CustomerAddressRepository.class);var order=mock(OrderLogisticsClient.class);var addr=new CustomerAddress();addr.setId(UUID.randomUUID());addr.setCustomer(c);addr.setCityId(UUID.randomUUID());addr.setZoneId(UUID.randomUUID());addr.setDefaultAddress(true);when(addresses.findByCustomerIdAndDefaultAddressTrue(c.getId())).thenReturn(Optional.of(addr));when(order.serviceability(any())).thenReturn(new ServiceabilityResponse(true,BigDecimal.ZERO,"30m",null,List.of(new LineServiceabilityResult(1L,p.getRetailerId(),true,null,BigDecimal.ZERO,"30m"))));var s=new CartServiceImpl(carts,items,products,ctx,wish,addresses,order,new FeignCallSupport(),noRetailerEnrichment());assertEquals(5,s.add(new CartItemRequest(1L,5)).quantity());}@Test void overStockRejected(){var products=mock(ProductRepository.class);var p=new Product();p.setId(1L);p.setStatus(com.lbos.commercecustomer.enums.ProductStatus.ACTIVE);p.setStock(5);when(products.findById(1L)).thenReturn(Optional.of(p));var ctx=mock(ContextSupport.class);when(ctx.customer()).thenReturn(new CustomerProfile());var s=new CartServiceImpl(mock(CustomerCartRepository.class),mock(CustomerCartItemRepository.class),products,ctx,mock(WishlistServiceImpl.class),mock(CustomerAddressRepository.class),mock(OrderLogisticsClient.class),new FeignCallSupport(),noRetailerEnrichment());assertThrows(com.lbos.commercecustomer.exception.BusinessValidationException.class,()->s.add(new CartItemRequest(1L,6)));}}